PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,email_verified_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(id_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,csrf_token TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS email_verification_tokens(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS password_reset_tokens(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS login_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,ip TEXT NOT NULL,action TEXT NOT NULL,attempted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS charts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS relationship_definitions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('self','parent','child','partner','other')),direction TEXT NOT NULL CHECK(direction IN('above','below','left','right')),line_style TEXT NOT NULL CHECK(line_style IN('solid','dashed','dotted')),line_color TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS gender_definitions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,shape TEXT NOT NULL CHECK(shape IN('circle','square','diamond')),fill_color TEXT NOT NULL,text_color TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS chart_nodes(id TEXT PRIMARY KEY,chart_id TEXT NOT NULL REFERENCES charts(id) ON DELETE CASCADE,relationship_definition_id TEXT NOT NULL REFERENCES relationship_definitions(id) ON DELETE RESTRICT,gender_definition_id TEXT NOT NULL REFERENCES gender_definitions(id) ON DELETE RESTRICT,anchor_node_id TEXT REFERENCES chart_nodes(id) ON DELETE SET NULL,memo TEXT NOT NULL DEFAULT '',font_size INTEGER NOT NULL DEFAULT 16 CHECK(font_size BETWEEN 8 AND 48),x REAL NOT NULL,y REAL NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS chart_edges(id TEXT PRIMARY KEY,chart_id TEXT NOT NULL REFERENCES charts(id) ON DELETE CASCADE,source_node_id TEXT NOT NULL REFERENCES chart_nodes(id) ON DELETE CASCADE,target_node_id TEXT NOT NULL REFERENCES chart_nodes(id) ON DELETE CASCADE,relationship_definition_id TEXT NOT NULL REFERENCES relationship_definitions(id) ON DELETE RESTRICT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY,applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_charts_user_updated ON charts(user_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_relationships_user_sort ON relationship_definitions(user_id,sort_order);
CREATE INDEX IF NOT EXISTS idx_genders_user_sort ON gender_definitions(user_id,sort_order);
CREATE INDEX IF NOT EXISTS idx_nodes_chart ON chart_nodes(chart_id);
CREATE INDEX IF NOT EXISTS idx_nodes_relationship ON chart_nodes(relationship_definition_id);
CREATE INDEX IF NOT EXISTS idx_nodes_gender ON chart_nodes(gender_definition_id);
CREATE INDEX IF NOT EXISTS idx_edges_chart ON chart_edges(chart_id);
CREATE INDEX IF NOT EXISTS idx_attempts_ip_action_time ON login_attempts(ip,action,attempted_at);
PRAGMA optimize;
